DROP TABLE IF EXISTS `water_data_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `water_data_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `name` varchar(100) NOT NULL COMMENT '任务名称',
  `source_id` bigint NOT NULL COMMENT '绑定的数据源ID',
  `cron_expression` varchar(100) DEFAULT NULL COMMENT '执行频率 (Cron表达式)',
  `query_sql_or_topic` text COMMENT '提取指令 (SQL/Topic/FilePath)',
  `auto_backfill` tinyint NOT NULL DEFAULT '0' COMMENT '是否自动触发历史补录 (0-否 1-是)',
  `interpolation` varchar(32) DEFAULT NULL COMMENT '插值策略',
  `target_entity` varchar(100) DEFAULT NULL COMMENT '目标实体表名或类别(如 sys_zone, sys_device, tdengine)',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '任务状态 (0正常 1停用)',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `last_run_time` datetime DEFAULT NULL COMMENT '最后执行时间',
  `last_run_status` char(1) DEFAULT NULL COMMENT '最后执行状态 (0-成功 1-失败)',
  `last_run_msg` text COMMENT '最后执行日志信息',
  `batch_size` int DEFAULT '0' COMMENT '单次拉取批次大小(0为不限制)',
  PRIMARY KEY (`id`),
  KEY `idx_water_data_task_source_id` (`source_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='【数据接入模块 - 数据接入任务表】数据接入任务配置表';
