--
-- Table structure for table `water_zone_metric_calc`
--

DROP TABLE IF EXISTS `water_zone_metric_calc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `water_zone_metric_calc` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '规则ID',
  `zone_code` varchar(50) NOT NULL COMMENT '分区编码',
  `metric_type` varchar(50) NOT NULL COMMENT '指标类型(如 supply:供水量, min_flow:夜间最小流量)',
  `point_code` varchar(50) NOT NULL COMMENT '测点编码',
  `calc_sign` int NOT NULL DEFAULT '1' COMMENT '计算符号(1加法 -1减法)',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `status` char(1) DEFAULT '0' COMMENT '状态',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_zone_code` (`zone_code`),
  KEY `idx_metric_type` (`metric_type`),
  KEY `idx_point_code` (`point_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='【水务基础模块 - 分区指标计算规则表】';
/*!40101 SET character_set_client = @saved_cs_client */;

